function legacyFinanceLink(db,type,id){const table=projectionSources[type];if(!table)return null;if(!db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name='pink_fx_transactions'").get())return null;return db.prepare('SELECT finance_entry_id FROM pink_fx_transactions WHERE projection_table=? AND projection_id=? ORDER BY id DESC LIMIT 1').get(table,Number(id));}
function customerFxAllocated(db,id,kind='receipt'){if(!db.prepare("SELECT 1 FROM sqlite_master WHERE name='pink_fx_customer_allocations'").get())return 0;return Number(db.prepare(`SELECT COALESCE(SUM(amount_krw),0) v FROM pink_fx_customer_allocations WHERE ${kind==='order'?'order_id':'receipt_id'}=? AND status='Active'`).get(id).v)}
