function posting(db,finance){
 if(finance.source_type==='Pink Salt FX Fee'){const fee=db.prepare('SELECT * FROM pink_fx_fee_debits WHERE id=? AND finance_entry_id=?').get(finance.source_id,finance.id);if(!fee)return {error:'Linked bank charge is missing.'};return {lines:JSON.parse(fee.proposal_json),context:{fx_transaction_id:fee.transaction_id},source_hash:crypto.createHash('sha256').update(fee.proposal_json).digest('hex')}}
 const tx=db.prepare('SELECT * FROM pink_fx_transactions WHERE id=? AND finance_entry_id=?').get(finance.source_id,finance.id);if(!tx)return {error:'The immutable Pink Salt FX transaction is missing.'};return {lines:JSON.parse(tx.proposal_json),context:{fx_transaction_id:tx.id,invoice_allocation_krw:tx.allocation_krw,bank_krw:tx.bank_krw,fee_krw:tx.fee_krw,fx_difference_krw:tx.fx_difference_krw},source_hash:crypto.createHash('sha256').update(tx.proposal_json).digest('hex')};}
function legacyPolicyReady(db,finance,journalId=null){
 if(journalId&&['Pink Salt FX Payment','Pink Salt FX Fee'].includes(finance.source_type)){const expected=posting(db,finance).lines;if(!expected)return false;const actual=db.prepare('SELECT * FROM accounting_journal_lines WHERE journal_entry_id=? ORDER BY id').all(journalId);if(actual.length!==expected.length||actual.some((l,i)=>Number(l.account_id)!==Number(expected[i].account_id)||Math.abs(l.debit_krw-expected[i].debit_krw)>.005||Math.abs(l.credit_krw-expected[i].credit_krw)>.005||Math.abs(l.original_amount-Number(expected[i].original_amount||0))>.005||l.original_currency!==(expected[i].original_currency||'KRW')))return false;}if(finance.source_type==='Pink Salt FX Fee')return (db.prepare('SELECT approved FROM pink_fx_policies WHERE business_unit_id=?').get(finance.business_unit_id)?.approved===1||require('./payment-approval-workflow').policyApproved(db,finance.id));
 if(finance.source_type!=='Pink Salt FX Payment')return true;const tx=db.prepare('SELECT * FROM pink_fx_transactions WHERE id=?').get(finance.source_id);if(!tx||tx.status!=='Active'||tx.confirmation_status==='Estimated')return false;
 if(tx.correction_of_id){const old=db.prepare('SELECT finance_entry_id FROM pink_fx_transactions WHERE id=?').get(tx.correction_of_id);if(old?.finance_entry_id&&db.prepare("SELECT 1 FROM accounting_journal_entries r JOIN accounting_journal_entries j ON j.id=r.reversal_of_id WHERE j.source_type='Finance Entry' AND j.source_id=? AND r.status IN ('Pending Review','Correction Required')").get(old.finance_entry_id))return false;}if(Math.abs(tx.fx_difference_krw)<.005&&tx.fee_krw<.005)return true;return (db.prepare('SELECT approved FROM pink_fx_policies WHERE business_unit_id=?').get(finance.business_unit_id)?.approved===1||require('./payment-approval-workflow').policyApproved(db,finance.id));}
function postingBlockers(db,f,journalId=null){
 if(!['Pink Salt FX Payment','Pink Salt FX Fee'].includes(f.source_type))return [];
 const tx=f.source_type==='Pink Salt FX Fee'?db.prepare('SELECT x.* FROM pink_fx_fee_debits fee JOIN pink_fx_transactions x ON x.id=fee.transaction_id WHERE fee.id=?').get(f.source_id):db.prepare('SELECT * FROM pink_fx_transactions WHERE id=?').get(f.source_id);
 const out=require('./pink-valuation-integrity').issues(tx,f.source_type==='Pink Salt FX Payment'?f:null);
 if(tx?.company_currency!=='KRW'&&Number(tx?.company_rate_to_krw)===1&&JSON.parse(tx.valuation_basis_json||'{}').identity_reason&&db.prepare('SELECT approved FROM pink_fx_policies WHERE business_unit_id=?').get(f.business_unit_id)?.approved!==1&&!require('./payment-approval-workflow').policyApproved(db,f.id))out.push({code:'IDENTITY_POLICY_PENDING',message:'An evidenced identity valuation requires CEO accounting-policy approval before posting.'});
 if(tx?.status!=='Active')out.push({code:'PAYMENT_NOT_ACTIVE',message:'The payment is reversed or no longer current. Open its current revision.'});
 if(tx?.confirmation_status==='Estimated')out.push({code:'RECIPIENT_UNCONFIRMED',message:'Confirm the recipient amount before posting.'});
 if(tx&&(Math.abs(tx.fx_difference_krw)>.005||tx.fee_krw>.005||f.source_type==='Pink Salt FX Fee')&&db.prepare('SELECT approved FROM pink_fx_policies WHERE business_unit_id=?').get(f.business_unit_id)?.approved!==1&&!require('./payment-approval-workflow').policyApproved(db,f.id))out.push({code:'POLICY_PENDING',message:'FX or fee accounting policy is awaiting CEO approval. Review the policy before final posting.'});
 if(tx?.correction_of_id){const old=db.prepare('SELECT finance_entry_id FROM pink_fx_transactions WHERE id=?').get(tx.correction_of_id);if(old?.finance_entry_id&&db.prepare("SELECT 1 FROM accounting_journal_entries r JOIN accounting_journal_entries j ON j.id=r.reversal_of_id WHERE j.source_type='Finance Entry' AND j.source_id=? AND r.status IN ('Pending Review','Correction Required')").get(old.finance_entry_id))out.push({code:'REVERSAL_PENDING',message:'Post the linked original journal reversal before posting this revision.'});}
 if(!out.length&&!legacyPolicyReady(db,f,journalId))out.push({code:'JOURNAL_SNAPSHOT_MISMATCH',message:'Journal lines do not match the immutable confirmed payment snapshot. Request Accounting correction and rebuild the unposted proposal.'});
 return out;
}
function policyReady(db,f,journalId=null){if(!require('./payment-approval-workflow').authorization(db,f).ready)return false;return postingBlockers(db,f,journalId).length===0;}
