 db.prepare("INSERT OR IGNORE INTO platform_entities(entity_type,module_key,entity_name,table_name,display_field,route_template,performance_class) VALUES('pink_fx_transaction','finance','Pink Salt Currency Settlement','pink_fx_transactions','reference','#psImports','Sensitive')").run();
