  const c={workflow,record_id:Number(id),business_unit_id:bu,invoice_currency:'KRW',invoice_carrying_rate:1,outstanding_krw:null,has_obligation:false,available_advance_krw:0,direction:'Out',advance_supported:false};
  let row;
