    c.payees=c.inline_recipient?[]:[...db.prepare('SELECT id,name FROM pink_salt_cost_payees WHERE business_unit_id=? AND active=1 ORDER BY name').all(bu).map(x=>({...x,type:'pink_salt_cost_payee'})),...db.prepare('SELECT id,name FROM pink_salt_suppliers WHERE business_unit_id=? AND active=1 ORDER BY name').all(bu).map(x=>({...x,type:'pink_salt_supplier'}))];
    if(c.inline_recipient){c.counterparty_type='other';c.counterparty_id=0;}
